module purge
module load gnu9 mpich

mkdir -p /mmfs1/home/ttryon/flames/bin/tests/AIAA2027/ShockWaterColumn
srun --mpi=pmi2 /home/ttryon/flames/bin/hydro2-2d-g++ /home/ttryon/flames/tests/AIAA2027/ShockWaterColumn/input_Ms7_N100
